class _RoundAction extends StatelessWidget{const _RoundAction({required this.icon,required this.label,required this.onTap,this.large=false});final IconData icon;final String label;final VoidCallback onTap;final bool large;@override Widget build(BuildContext c)=>Column(children:[InkWell(onTap:onTap,borderRadius:BorderRadius.circular(60),child:Container(width:large?92:64,height:large?92:64,decoration:BoxDecoration(color:large?ui.OpenApp.lime:Colors.white,shape:BoxShape.circle,boxShadow:[BoxShadow(color:(large?ui.OpenApp.lime:Colors.black).withValues(alpha:large?.24:.07),blurRadius:24)]),child:Icon(icon,size:large?39:28))),const SizedBox(height:8),Text(label,style:TextStyle(fontSize:large?16:13,fontWeight:large?FontWeight.w800:FontWeight.w600))]);}
